import{H as e,V as t,et as n,j as r}from"./chunks/framework.C_EfTa_6.js";var i=JSON.parse(`{"title":"Core 装机","description":"","frontmatter":{"title":"Core 装机","order":48},"headers":[],"relativePath":"kernel/equip/motherboard/core.md","filePath":"kernel/equip/motherboard/core.md"}`),a={name:`kernel/equip/motherboard/core.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="intel-消费级-core-装机生态" tabindex="-1">Intel 消费级 Core 装机生态 <a class="header-anchor" href="#intel-消费级-core-装机生态" aria-label="Permalink to “Intel 消费级 Core 装机生态”">​</a></h1><p>Intel 消费级 CPU 用 Core i3/i5/i7/i9 命名（2024 年起改名 Core Ultra 5/7/9），对应一个跟服务器至强、工作站至强完全不同的接口和主板生态。本文按代际展开 Intel 消费级平台的接口变迁、当前二手性价比、以及与至强/EPYC 的边界——帮你搞清楚什么时候该选 Core、什么时候该上工作站、什么时候该上服务器。</p><h2 id="接口代际总览" tabindex="-1">接口代际总览 <a class="header-anchor" href="#接口代际总览" aria-label="Permalink to “接口代际总览”">​</a></h2><p>Intel 消费级接口从 2015 年到现在换了 4 次，每代约 3-5 年。理解这张表是装机第一步。</p><table tabindex="0"><thead><tr><th>接口</th><th>推出时间</th><th>配套 CPU 代际</th><th>配套芯片组</th><th>当前二手价值</th></tr></thead><tbody><tr><td><strong>LGA 1151</strong></td><td>2015-2021</td><td>6/7/8/9 代 Skylake/Coffee Lake + 10/11 代 Comet/Rocket Lake</td><td>H110/B150/H170/Z170 → B250/Z270 → H310/B360/H370/Z370/Z390 → B460/Z490</td><td>几乎无价值</td></tr><tr><td><strong>LGA 1200</strong></td><td>2020-2021</td><td>10/11 代 Comet/Rocket Lake（部分 Comet Lake 同时支持 LGA 1200 与 LGA 1151 修正版）</td><td>H410/B460/H470/Z490 → H510/B560/H570/Z590</td><td>接近零</td></tr><tr><td><strong>LGA 1700</strong></td><td>2021-2024</td><td>12/13/14 代 Alder/Raptor Lake</td><td>H610/B660/H670/Z690 → B760/Z790</td><td><strong>主流二手</strong></td></tr><tr><td><strong>LGA 1851</strong></td><td>2024+</td><td>Core Ultra 200S / 200S Plus（Arrow Lake-S）</td><td>Z890 / B860 / H810</td><td>新品</td></tr></tbody></table><p><strong>关键事实</strong>：</p><ul><li>同一接口内不同代 CPU 大多兼容（如 LGA 1700 跑 12 代到 14 代），升级只需刷 BIOS</li><li><strong>跨代不兼容</strong>——LGA 1700 主板装不上 LGA 1851 CPU，反之亦然</li><li>笔记本 Core Ultra 用 BGA 焊接，<strong>不能升级</strong>——选购时直接看整机配置</li></ul><h2 id="各代可玩性评价" tabindex="-1">各代可玩性评价 <a class="header-anchor" href="#各代可玩性评价" aria-label="Permalink to “各代可玩性评价”">​</a></h2><h3 id="lga-1151-6-11-代-2015-2021" tabindex="-1">LGA 1151（6-11 代，2015-2021） <a class="header-anchor" href="#lga-1151-6-11-代-2015-2021" aria-label="Permalink to “LGA 1151（6-11 代，2015-2021）”">​</a></h3><p><strong>一句话评价：2026 年不要碰</strong>。原因：</p><ul><li>IPC 远落后于现代 CPU（Skylake 6 代 i7-6700K 已被 13 代 i5-13400 单核超越）</li><li>二手价虽极低（i7-6700K + B150 主板整机 200-400 元），但性能浪费电力</li><li>DDR4 平台能效比差，6 代满载 95W 的 i7 跑不出 12 代 i5 的性能</li><li><strong>唯一价值</strong>：极致预算下&quot;能开机就行&quot;的备用机或软路由</li></ul><p>注意：6/7 代（Skylake/Kaby Lake）用 LGA 1151 v1，8/9 代（Coffee Lake）用 LGA 1151 v2，物理接口相同但<strong>针脚定义不同</strong>——8 代 i5-8400 装到 Z170 主板上点不亮。10/11 代又改回 LGA 1200 了。整个 LGA 1151 时代坑很多，2026 年完全不值得折腾。</p><h3 id="lga-1200-10-11-代-2020-2021" tabindex="-1">LGA 1200（10/11 代，2020-2021） <a class="header-anchor" href="#lga-1200-10-11-代-2020-2021" aria-label="Permalink to “LGA 1200（10/11 代，2020-2021）”">​</a></h3><p><strong>一句话评价：除非捡白菜价，否则跳过</strong>。比 LGA 1151 好一点（多了 PCIe 4.0、Wi-Fi 6），但 10 代 i9-10900K 的 IPC 与 12 代 i5-12600K 接近——后者还便宜。二手 i5-11400 + B560 整机 600-900 元，性能被 13 代 i5-13400 全面压制。</p><h3 id="lga-1700-12-13-14-代-2021-2024" tabindex="-1">LGA 1700（12/13/14 代，2021-2024） <a class="header-anchor" href="#lga-1700-12-13-14-代-2021-2024" aria-label="Permalink to “LGA 1700（12/13/14 代，2021-2024）”">​</a></h3><p><strong>一句话评价：当前二手性价比最佳</strong>。三个原因：</p><ol><li><strong>12 代是 Intel 的翻身仗</strong>——Alder Lake 引入大小核架构（P-core + E-core），IPC 暴涨 19%，单核直接追上 AMD Zen 3</li><li><strong>13 代（Raptor Lake）巩固优势</strong>——i5-13600K（6P+8E, 14C20T, 5.1 GHz）单核追平 Zen 4，多核碾压</li><li><strong>14 代（Raptor Lake Refresh）拉高频</strong>——i9-14900K 拉到 6.0 GHz，但功耗惊人（满载 350W+）</li></ol><p><strong>关键推荐</strong>（2026 年二手视角）：</p><table tabindex="0"><thead><tr><th>CPU</th><th>规格</th><th>二手价</th><th>推荐场景</th></tr></thead><tbody><tr><td>i5-12400 / 12400F</td><td>6P+0E, 6C12T, 4.4 GHz</td><td>350-500 元</td><td>主流办公 + 轻度游戏</td></tr><tr><td>i5-13400 / 13400F</td><td>6P+4E, 10C16T, 4.6 GHz</td><td>600-800 元</td><td>性价比最高的现代 i5</td></tr><tr><td>i5-13600K / KF</td><td>6P+8E, 14C20T, 5.1 GHz</td><td>900-1200 元</td><td>性价比旗舰，能跑 4K 游戏</td></tr><tr><td>i7-13700K / KF</td><td>8P+8E, 16C24T, 5.4 GHz</td><td>1500-2000 元</td><td>视频剪辑 + 直播 + 游戏</td></tr><tr><td>i9-13900K / KF</td><td>8P+16E, 24C32T, 5.8 GHz</td><td>2000-2800 元</td><td>重度多线程（不推荐 14 代 14900K）</td></tr><tr><td>i9-14900K</td><td>8P+16E, 24C32T, 6.0 GHz</td><td>2500-3500 元</td><td>⚠️ 跳过，14 代有稳定性问题</td></tr></tbody></table><p><strong>14 代稳定性问题</strong>：i9-13900K/14900K 在 2024-2025 年频繁出现崩溃、蓝屏、芯片缩氧问题，Intel 推了多次 microcode 修复但没根治。<strong>2026 年建议避开 i9-14 代</strong>——同样的钱买 i9-13900K 更稳，或直接上 AMD Ryzen 9 7900X/7950X（AM5 平台）。</p><p><strong>LGA 1700 主板芯片组选型</strong>：</p><table tabindex="0"><thead><tr><th>芯片组</th><th>二手价</th><th>推荐 CPU</th><th>关键特性</th></tr></thead><tbody><tr><td>H610</td><td>200-400</td><td>12/13 代 i5 非 K</td><td>入门 PCIe 4.0、DDR4/DDR5、不能超频</td></tr><tr><td>B660</td><td>300-600</td><td>12/13 代 i5/i7 非 K</td><td>主流性价比，内存超频支持</td></tr><tr><td>B760</td><td>400-800</td><td>13 代 i5/i7</td><td>H610 升级版，加 Wi-Fi 6E</td></tr><tr><td>H770</td><td>500-900</td><td>13 代 i7</td><td>B760 + 多一个 M.2</td></tr><tr><td>Z690</td><td>500-1200</td><td>12 代 K 系列</td><td>CPU 超频、DDR5 支持</td></tr><tr><td>Z790</td><td>700-1500</td><td>13/14 代 K 系列</td><td>Z690 升级版，加 USB 3.2 Gen 2x2</td></tr></tbody></table><p><strong>内存选择</strong>：LGA 1700 同时支持 DDR4 和 DDR5。2026 年建议<strong>DDR5</strong>——DDR4 与 DDR5 主板差价已收窄（200-300 元），DDR5 频率从 4800 起步到 8000+，带宽远高于 DDR4 的极限 3200。但要注意 DDR4 和 DDR5 <strong>不能混用</strong>，主板芯片组型号尾缀区分（如 Z790 DDR4 vs Z790 DDR5）。</p><h3 id="lga-1851-core-ultra-200s-200s-plus-2024" tabindex="-1">LGA 1851（Core Ultra 200S / 200S Plus，2024+） <a class="header-anchor" href="#lga-1851-core-ultra-200s-200s-plus-2024" aria-label="Permalink to “LGA 1851（Core Ultra 200S / 200S Plus，2024+）”">​</a></h3><p><strong>一句话评价：观望中，新架构但游戏性能没明显提升</strong>。</p><p>Core Ultra 200S（Arrow Lake-S）是 Intel 2024 年底推出的桌面平台，关键变化：</p><ul><li>取消超线程（每个 P-core 单线程）</li><li>加入 NPU（神经处理单元），但 Windows AI 应用尚未成熟</li><li>内存仅支持 DDR5（不再有 DDR4 主板）</li><li>功耗表现改善（i9-285K 满载 250W vs 14900K 的 350W+）</li></ul><p>但实测<strong>游戏性能不如 13/14 代</strong>——Arrow Lake 在游戏上比 Raptor Lake 倒退约 5-10%。原因可能是调度问题或 NPU 占用功耗预算。</p><p>2026 年 3 月发布的 <strong>Core Ultra 200S Plus 系列</strong>（270K Plus、250K/KF Plus）是 Arrow Lake Refresh，核心数更多、die-to-die 频率提升 900 MHz。Intel 在新闻稿里说&quot;更多核心&quot;，但具体游戏性能需要等独立评测。</p><p><strong>推荐</strong>：</p><ul><li>如果已经在用 LGA 1700 + 13 代 i5/i7，<strong>没有升级理由</strong></li><li>如果从零开始装机且想用最新 Intel，<strong>观望 200S Plus 等独立评测</strong></li><li>如果要现在买——<strong>LGA 1700 + 13 代 i5-13600K 是 2026 年 Intel 装机最稳的选择</strong></li></ul><h2 id="主板品牌与型号" tabindex="-1">主板品牌与型号 <a class="header-anchor" href="#主板品牌与型号" aria-label="Permalink to “主板品牌与型号”">​</a></h2><p>消费级主板不像服务器主板（Supermicro 一家独大）那样集中。华擎、华硕、技嘉、微星是四大主力，还有七彩虹、铭瑄、映泰等小厂。</p><h3 id="芯片组对应主流品牌" tabindex="-1">芯片组对应主流品牌 <a class="header-anchor" href="#芯片组对应主流品牌" aria-label="Permalink to “芯片组对应主流品牌”">​</a></h3><table tabindex="0"><thead><tr><th>芯片组</th><th>华硕（ASUS）</th><th>技嘉（GIGABYTE）</th><th>微星（MSI）</th><th>华擎（ASRock）</th></tr></thead><tbody><tr><td>Z790</td><td>ROG Strix / Prime / TUF Gaming</td><td>AORUS Master/Elite</td><td>MAG / MPG / MEG</td><td>Taichi / Steel Legend / PG</td></tr><tr><td>B760</td><td>ROG Strix / Prime / TUF</td><td>Gaming X / UD</td><td>MAG / Pro</td><td>Pro RS / Steel Legend</td></tr><tr><td>H610</td><td>Prime</td><td>UD / Gaming</td><td>Pro</td><td>H610M-HVS</td></tr></tbody></table><p><strong>性价比分层</strong>（同一芯片组内）：</p><ul><li><strong>入门</strong>：H610、B760 入门款——单 M.2、2 条内存槽、基本 VRM</li><li><strong>主流</strong>：B760 中端、B760M 板型——双 M.2、4 内存槽、良好 VRM</li><li><strong>高端</strong>：Z790 中端——4 M.2、Wi-Fi 6E/7、2.5G 网口、强化 VRM</li><li><strong>旗舰</strong>：Z790 顶级（ROG Maximus / AORUS Xtreme / MEG Godlike）——极致超频、10G 网口、雷电 4</li></ul><p><strong>选购原则</strong>：</p><ul><li>不超频选 B760（H610 也行但扩展太差）</li><li>超频选 Z790，但只看中端型号（高端溢价过高）</li><li>ITX 板型溢价 30-50%，M-ATX 是甜点</li><li><strong>Wi-Fi 6E/7</strong> 在 2026 年值得选——Wi-Fi 6 路由已是主流</li></ul><h3 id="二线品牌" tabindex="-1">二线品牌 <a class="header-anchor" href="#二线品牌" aria-label="Permalink to “二线品牌”">​</a></h3><ul><li><strong>映泰</strong>：H610/B760 入门款便宜，但 BIOS 更新慢、VRM 缩水</li><li><strong>铭瑄</strong>：H610 极限便宜（200 元出头），但扩展槽少</li><li><strong>七彩虹</strong>：中端为主，CVN / iGame 系列比同芯片组华硕便宜 30%</li></ul><p>这些品牌适合<strong>预算极致压缩</strong>的场景，但要注意二手保修问题——主板是计算机里寿命最长的部件之一，但故障率也随品牌差异明显。</p><h2 id="散热方案" tabindex="-1">散热方案 <a class="header-anchor" href="#散热方案" aria-label="Permalink to “散热方案”">​</a></h2><p>LGA 1700 与 LGA 1851 使用相同的散热器扣具（ILM 略有差异但兼容）。消费级散热器市场比服务器市场成熟得多，几乎所有塔式风冷和水冷都直接支持。</p><p><strong>推荐组合</strong>：</p><table tabindex="0"><thead><tr><th>CPU 功耗</th><th>散热方案</th><th>代表产品</th><th>价格区间</th></tr></thead><tbody><tr><td>65-95W（i5 非 K）</td><td>单塔单/双扇</td><td>利民 AX120R SE、PA120 SE</td><td>80-200 元</td></tr><tr><td>125-150W（i5 K / i7 非 K）</td><td>单塔双扇或 240 水冷</td><td>猫头鹰 NH-U12S、PA120</td><td>150-400 元</td></tr><tr><td>150-250W（i7 K / i9 非 K）</td><td>双塔双扇或 360 水冷</td><td>猫头鹰 NH-D15、DeepCool AK620</td><td>300-800 元</td></tr><tr><td>250W+（i9 K）</td><td>360 一体水冷或定制</td><td>猫头鼠 NH-D15 + 风扇升级、Arctic LF3 360</td><td>500-1500 元</td></tr></tbody></table><p>LGA 1700 散热注意事项：<strong>ILM 弯曲问题</strong>。Intel LGA 1700 的 ILM（Independent Loading Mechanism）在压力下会轻微弯曲，导致 CPU 与散热器接触不均。现象是 CPU 温度比同型号老平台高 5-10°C。解决方法：</p><ul><li>买带 LGA 1700 专用扣具的散热器（多数新品已支持）</li><li>或贴 Thermalright LGA 1700 弯曲校正片（20 元）</li><li>或更换接触框（如 Thermalright LGA1700-BCF，80-150 元）</li></ul><p>13/14 代 i7/i9 满载功耗飙升后，这个问题更明显——预算足够建议直接上<strong>接触框 + 高端双塔</strong>组合。</p><h2 id="内存采购" tabindex="-1">内存采购 <a class="header-anchor" href="#内存采购" aria-label="Permalink to “内存采购”">​</a></h2><p>LGA 1700/1851 时代，DDR4 与 DDR5 并存到 2024 年。2026 年建议直接 DDR5。</p><p><strong>DDR5 推荐</strong>：</p><ul><li>起步：DDR5-4800 / 5200 16GB×2 ≈ 400-500 元</li><li>主流：DDR5-5600 / 6000 16GB×2 ≈ 500-700 元（甜点，CL30/CL36）</li><li>高频：DDR5-6400 / 7200 16GB×2 ≈ 800-1500 元（Intel XMP 3.0 平台能跑到 8000+）</li><li>大容量：32GB×2 ≈ 1000-1500 元（视频剪辑、AI 本地推理）</li></ul><p><strong>主板兼容性陷阱</strong>：DDR5 主板对内存控制器敏感，特别是高频条。建议购买前查主板 QVL（Qualified Vendor List）——主板官网列出验证过的内存型号，能保证稳定运行在标称频率。</p><p><strong>XMP/EXPO</strong>：DDR5 上 Intel 叫 XMP 3.0（AMD 叫 EXPO）。要在主板 BIOS 里手动开启才能跑标称频率，不开启就是 JEDEC 默认的 4800。XMP 不是即插即用。</p><h2 id="装机方案参考" tabindex="-1">装机方案参考 <a class="header-anchor" href="#装机方案参考" aria-label="Permalink to “装机方案参考”">​</a></h2><h2 id="与工作站、服务器的边界" tabindex="-1">与工作站、服务器的边界 <a class="header-anchor" href="#与工作站、服务器的边界" aria-label="Permalink to “与工作站、服务器的边界”">​</a></h2><p>把消费级 Core 跟 xeon.md 里的两条至强线对比，决策要点：</p><table tabindex="0"><thead><tr><th>维度</th><th>消费级 Core</th><th>工作站至强 W</th><th>服务器至强 E5/Scalable</th></tr></thead><tbody><tr><td>内存</td><td>DDR4/DDR5 UDIMM</td><td>DDR4/DDR5 UDIMM（部分支持 ECC UDIMM）</td><td>DDR4 RDIMM</td></tr><tr><td>ECC</td><td>否（部分 Z 主板支持但罕见）</td><td>部分支持</td><td>必须</td></tr><tr><td>主板</td><td>H610/Z790（消费级）</td><td>X299/W790（消费级 HEDT）</td><td>C612/C621（服务器）</td></tr><tr><td>多路</td><td>否</td><td>否</td><td>是</td></tr><tr><td>核心数</td><td>24C（i9）</td><td>56C（W9）</td><td>56C+（双路 Platinum）</td></tr><tr><td>单核</td><td>5-6 GHz</td><td>4-4.8 GHz</td><td>2-3 GHz</td></tr><tr><td>内存通道</td><td>2</td><td>4-8</td><td>4-8（双路 12+）</td></tr><tr><td>二手市场</td><td>极活跃</td><td>适中</td><td>庞大</td></tr><tr><td>价格区间</td><td>整机 2000-15000 元</td><td>整机 3000-30000 元</td><td>整机 1000-5000 元</td></tr></tbody></table><p><strong>决策流程</strong>：</p><ul><li><strong>要 ECC + 多核 + 便宜内存</strong> → 服务器至强（特别是 E5 v4）或 EPYC Rome/Milan</li><li><strong>要高频 + 单核 + 消费级便利</strong> → 消费级 Core i5/i7 K 系列，或工作站至强 W-2100</li><li><strong>要最新 Intel 平台 + 不在乎价格</strong> → 消费级 Core Ultra 200S Plus 或工作站至强 W-2400</li><li><strong>要核显 + 日常使用 + 性价比</strong> → <strong>消费级 Core i5</strong>（最优解）</li></ul><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to “常见陷阱”">​</a></h2><ol><li><p><strong>8 代 i5/i7 装到 100/200 系主板</strong>：LGA 1151 v1 和 v2 物理相同但针脚定义不同。8 代 CPU 装到 Z170 上点不亮。<strong>购买二手主板时确认 BIOS 已经刷过 8 代 CPU 微码</strong>。</p></li><li><p><strong>LGA 1700 12 代非 K 锁 SA 电压</strong>：12 代非 K（i5-12400 等）的内存超频依赖 SA 电压调节，部分 B660 主板 BIOS 默认锁住。需要刷新版 BIOS 或选高端 B660。</p></li><li><p><strong>i9-13900K/14900K 稳定性问题</strong>：前文已述。2026 年买二手建议避开 14 代，13 代 i9 性能差异不到 5% 但稳定性好得多。</p></li><li><p><strong>DDR5 内存条兼容</strong>：DDR5 比 DDR4 复杂得多——PMIC 电源管理芯片、On-die ECC、温度传感器。<strong>同一品牌不同批次可能有差异</strong>，建议从主板 QVL 列表里选。</p></li><li><p><strong>14 代 i9 主板 BIOS 限制</strong>：部分早期 Z790 主板 BIOS 没有正确实现 14 代电压管理，导致 14900K 在低负载时也会拉高频高电压。建议买 Z790 后期型号（2024 年后出货的）或刷最新 BIOS。</p></li><li><p><strong>PCIe 5.0 显卡功耗</strong>：RTX 5090 的 575W TDP 通过 12VHPWR 接口需要 ATX 3.0 电源（带原生 12VHPWR 输出）。老电源用 8-pin 转接线会有烧接口风险。</p></li><li><p><strong>机箱散热与 i9 共存</strong>：i9-13900K/14900K 满载功耗大，机箱风道设计至关重要。建议至少前 2 进 + 后 1 出的风扇配置，必要时加顶部排风。如果用 360 水冷，确保冷排有足够的风扇风量（建议 2000+ RPM 风扇）。</p></li><li><p><strong>集成显卡 vs 独立显卡</strong>：i5-12400/13400 等带核显（标识带 G 或无 F 后缀），可以省显卡但游戏性能有限。如果装机时没买显卡，确认 CPU 是带核显版本。<strong>F 后缀（如 12400F）不带核显</strong>——必须配独立显卡。</p></li></ol>`,63)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};